import { useRef, useState } from 'react';
import { TokenSearchField } from '@kerfjs/ui/token-search-field';
import '@kerfjs/ui/layout.css';

export type FilterToken = { id: string; label: string; value: string };
export type SearchValue = { text: string; tokens: FilterToken[] };
export type Caret = { tokenIndex: number; offset: number };
export type Suggestion = { id: string; label: string; token: FilterToken };
type FieldHandle = { focus: () => void; setCaret: (caret: Caret) => void };
type Props = {
  value: SearchValue;
  onChange: (value: SearchValue) => void;
  parse: (text: string, current: SearchValue) => { value: SearchValue; caret: Caret };
  suggest: (value: SearchValue) => Suggestion[];
  submit: (value: SearchValue) => void;
};
// This adapter illustrates required public interactions. The frozen guidance
// does not supply TokenSearchField's props, event payloads or caret handle;
// bind these names to its actual documented API before compiling.
export function SearchEditor({ value, onChange, parse, suggest, submit }: Props) {
  const field = useRef<FieldHandle>(null);
  const [announcement, announce] = useState('');
  const [editing, edit] = useState<string | null>(null);
  const [caret, rememberCaret] = useState<Caret>({ tokenIndex: 0, offset: 0 });
  const suggestions = suggest(value);
  function update(next: SearchValue, nextCaret: Caret, message: string) {
    onChange(next);
    rememberCaret(nextCaret);
    announce(message);
    requestAnimationFrame(() => {
      field.current?.focus();
      field.current?.setCaret(nextCaret);
    });
  }
  function remove(id: string) {
    const index = value.tokens.findIndex(token => token.id === id);
    if (index < 0) return;
    update({ ...value, tokens: value.tokens.filter(token => token.id !== id) },
      { tokenIndex: index, offset: 0 }, 'Filter removed.');
    edit(null);
  }
  function choose(suggestion: Suggestion) {
    const index = value.tokens.findIndex(token => token.id === editing);
    const tokens = [...value.tokens];
    const insertion = index >= 0 ? index : Math.min(caret.tokenIndex, tokens.length);
    tokens.splice(insertion, index >= 0 ? 1 : 0, suggestion.token);
    update({ ...value, tokens }, { tokenIndex: insertion + 1, offset: 0 },
      index >= 0 ? 'Filter replaced.' : 'Filter added.');
    edit(null);
  }
  return <form className="kui-layout" role="search" aria-label="Workspace search"
    onSubmit={event => { event.preventDefault(); submit(value); }}>
    <TokenSearchField ref={field} aria-label="Search workspace with filters"
      value={value} onChange={onChange} onCaretChange={rememberCaret}
      onTokenRemove={remove} onTokenEdit={(id: string) => { edit(id); announce('Choose a replacement filter.'); }}
      onCommitText={(text: string) => {
        const parsed = parse(text, value); update(parsed.value, parsed.caret, 'Search updated.');
      }}
      onClear={() => { edit(null); update({ text: '', tokens: [] }, { tokenIndex: 0, offset: 0 }, 'Search cleared.'); }} />
    <button type="submit">Search</button>
    {suggestions.length > 0 && <section aria-label={editing ? 'Replacement filters' : 'Suggested filters'}>
      <ul>{suggestions.map(suggestion => <li key={suggestion.id}>
        <button type="button" onClick={() => choose(suggestion)}>{suggestion.label}</button>
      </li>)}</ul>
      {editing && <button type="button" onClick={() => { edit(null); field.current?.focus(); }}>Cancel replacement</button>}
    </section>}
    <p role="status" aria-live="polite">{announcement}</p>
  </form>;
}
// Preserve the primitive's single searchbox, keyboard token editing/removal,
// clear action and caret behavior; do not replace them with a parallel input.
// Suggestions use ordinary keyboard-operable buttons, avoiding incomplete
// combobox semantics. Parsing, suggestion production and query state stay here.
